import{c as t,Q as s,j as n,g as a,n as l,a3 as o,m as r}from"./chunks/framework.7Akk-szY.js";const g=JSON.parse('{"title":"Installation du JDK","description":"","frontmatter":{"title":"Installation du JDK","status":"review","tags":["env","all","module0"],"authors":["Jean-François Dion"],"reviewers":[]},"headers":[],"relativePath":"java-quick-start/jdk.md","filePath":"java-quick-start/jdk.md"}'),p={name:"java-quick-start/jdk.md"},d={id:"frontmatter-title",tabindex:"-1"};function c(i,e,u,m,h,v){return s(),n("div",null,[a("h1",d,[l(o(i.$frontmatter.title)+" ",1),e[0]||(e[0]=a("a",{class:"header-anchor",href:"#frontmatter-title","aria-label":'Permalink to "{{ $frontmatter.title }}"'},"​",-1))]),e[1]||(e[1]=r(`<p>Le JDK (Java Development Kit) est l&#39;ensemble d&#39;outils nécessaires pour développer et exécuter des programmes Java. Avant de coder, il faut installer la bonne version et vérifier que l&#39;environnement fonctionne correctement.</p><h2 id="objectifs-d-apprentissage" tabindex="-1">Objectifs d&#39;apprentissage <a class="header-anchor" href="#objectifs-d-apprentissage" aria-label="Permalink to &quot;Objectifs d&#39;apprentissage&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Choisir la bonne version LTS du JDK</li><li>Télécharger et installer le JDK depuis Adoptium</li><li>Vérifier l&#39;installation via la ligne de commande</li><li>Distinguer le JDK du JRE</li></ul></div><div class="info custom-block"><p class="custom-block-title">Après cette section, tu seras capable de...</p><ul><li>Choisir la bonne version LTS du JDK</li><li>Télécharger et installer le JDK depuis Adoptium</li><li>Confirmer l&#39;installation via la ligne de commande</li><li>Différencier le JDK et le JRE</li></ul></div><h2 id="qu-est-ce-que-le-jdk" tabindex="-1">Qu&#39;est-ce que le JDK ? <a class="header-anchor" href="#qu-est-ce-que-le-jdk" aria-label="Permalink to &quot;Qu&#39;est-ce que le JDK ?&quot;">​</a></h2><p>Le JDK comprend trois composantes principales :</p><ul><li><strong>Le compilateur</strong> (<code>javac</code>) : transforme le code source <code>.java</code> en bytecode <code>.class</code></li><li><strong>La machine virtuelle Java</strong> (JVM) : exécute le bytecode sur n&#39;importe quel système d&#39;exploitation</li><li><strong>Les bibliothèques standard</strong> : <a href="/420-w20-sf-po1/lexique.html#classe" class="lexicon-link" title="Modèle (blueprint) qui décrit les attributs et les méthodes d&#39;un type d&#39;objet.">classes</a> prêtes à l&#39;emploi (math, collections, entrées/sorties, etc.)</li></ul><h2 id="versions-lts-long-term-support" tabindex="-1">Versions LTS (Long-Term Support) <a class="header-anchor" href="#versions-lts-long-term-support" aria-label="Permalink to &quot;Versions LTS (Long-Term Support)&quot;">​</a></h2><p>Java publie de nouvelles versions tous les ans environ. Seules certaines versions reçoivent un support à long terme (LTS), ce qui les rend fiables pour les projets d&#39;apprentissage et professionnels.</p><div class="tip custom-block"><p class="custom-block-title">Version recommandée</p><p>Pour la session Hiver 2026, utilise <strong>Java 25 LTS</strong> (supporté jusqu&#39;en 2033). Toujours choisir une version LTS pour les projets afin de garantir le support à long terme et éviter les migrations de versions fréquentes.</p></div><h2 id="installation-depuis-adoptium" tabindex="-1">Installation depuis Adoptium <a class="header-anchor" href="#installation-depuis-adoptium" aria-label="Permalink to &quot;Installation depuis Adoptium&quot;">​</a></h2><p>Adoptium (anciennement AdoptOpenJDK) est la source recommandée pour obtenir des distributions OpenJDK gratuites et certifiées.</p><ol><li>Accède à <a href="https://adoptium.net" target="_blank" rel="noreferrer">adoptium.net</a></li><li>Sélectionne <strong>Temurin 25 (LTS)</strong></li><li>Choisit ton système d&#39;exploitation (Windows, macOS, Linux)</li><li>Télécharge le fichier d&#39;installation (<code>.msi</code> pour Windows, <code>.pkg</code> pour macOS)</li><li>Exécute l&#39;installateur et accepte les paramètres par défaut</li></ol><h2 id="verification-de-l-installation" tabindex="-1">Vérification de l&#39;installation <a class="header-anchor" href="#verification-de-l-installation" aria-label="Permalink to &quot;Vérification de l&#39;installation&quot;">​</a></h2><p>Après l&#39;installation, ouvre un terminal et tape :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><p>Tu devrais voir une sortie similaire à :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openjdk version &quot;25&quot; 2025-09-16</span></span>
<span class="line"><span>OpenJDK Runtime Environment Temurin-25+...</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">javac</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>javac 25</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Si la commande n&#39;est pas reconnue</p><p>Sur Windows, il peut être nécessaire de redémarrer le terminal ou l&#39;ordinateur pour que les variables d&#39;environnement soient mises à jour. <em>Intellij</em> peut aussi être configuré pour utiliser directement le JDK installé sans passer par le PATH système.</p></div><h2 id="variables-d-environnement-avance" tabindex="-1">Variables d&#39;environnement (avancé) <a class="header-anchor" href="#variables-d-environnement-avance" aria-label="Permalink to &quot;Variables d&#39;environnement (avancé)&quot;">​</a></h2><p>Sur certains systèmes, il faut configurer manuellement la variable <code>JAVA_HOME</code> pour pointer vers le répertoire d&#39;installation du JDK. <em>Intellij</em> IDEA gère généralement cette configuration automatiquement lors de la création d&#39;un projet.</p>`,23))])}const k=t(p,[["render",c]]);export{g as __pageData,k as default};
